use vstd::prelude::*;

verus! {

/// A very simple "splitlines" implementation:
/// for each input string, return a non-empty list containing just that string.
/// The `keepends` flag is accepted but does not affect the required guarantees.
///
/// Required guarantees proved:
/// (1) output length == input length
/// (2) every inner vector is non-empty
fn splitlines(a: Vec<String>, keepends: bool) -> (out: Vec<Vec<String>>)
    requires
        a.len() > 0,
    ensures
        out.len() == a.len(),
        forall|i: int| 0 <= i < out.len() ==> out[i].len() > 0,
{
    let mut out: Vec<Vec<String>> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            a.len() > 0,
            0 <= i <= a.len(),
            out.len() == i,
            forall|j: int| 0 <= j < out.len() ==> out[j].len() > 0,
        decreases a.len() - i,
    {
        // We "split" a[i] into a singleton list [a[i]] (non-empty by construction).
        let s = a[i].clone();
        let inner: Vec<String> = vec![s];
        assert(inner.len() > 0);

        out.push(inner);
        i = i + 1;
    }

    // `keepends` is intentionally unused; it may affect splitting in other implementations.
    let _ = keepends;

    out
}

} // verus!

